export function requestLog(req, res, next) {
  logger.info(`${req.method} ${req.path}`);
  next();
}

message.content:
Plan: generate a `request_id` (or honor an incoming `x-request-id`) in the logging middleware, stash it on `req`, bind it into a child logger, and forward the header upstream in `buildHeaders`. That gives you end-to-end correlation without touching every call site:

```js
req.id = req.get('x-request-id') ?? crypto.randomUUID();
req.log = logger.child({ request_id: req.id });
```

Applying it to the middleware and the upstream header builder.

