const BASE_MS = 5_000;
const CAP_MS = 30 * 60_000;

async deliver(evt, attempt = 0) {
  try {
    await post(evt.url, evt.payload);
  } catch (err) {
    if (attempt + 1 >= MAX_ATTEMPTS) return this.deadLetter(evt, err);
    metrics.inc('webhook_retry');
    const delay = Math.min(CAP_MS, BASE_MS * 2 ** attempt);
    setTimeout(() => this.deliver(evt, attempt + 1), Math.random() * delay);
  }
}"}

