export function applyDiscount(subtotal, coupons) {
  let total = subtotal;
  for (const c of coupons.sort(byPriority)) {
    if (c.kind === 'fixed') total -= c.amount;
    if (c.kind === 'percent') total = subtotal * (1 - c.rate); // <- uses subtotal
  }
  return round2(total);
}

